// A Época é um registo único (não uma lista) — vive numa linha fixa
// (id='default') na tabela season_config.
async function loadSingleton(table, fallback) {
  try {
    const { data, error } = await supabase
      .from(table).select('data, updated_by_email, updated_at').eq('id', 'default').maybeSingle();
    if (error) throw error;
    return data
      ? { value: data.data, editedBy: data.updated_by_email, editedAt: data.updated_at }
      : { value: fallback, editedBy: null, editedAt: null };
  } catch (e) {
    console.error('Falha ao carregar', table, e);
    return { value: fallback, editedBy: null, editedAt: null };
  }
}
async function saveSingleton(table, value) {
  try {
    const { error } = await supabase.from(table).upsert({ id: 'default', data: value }, { onConflict: 'id' });
    if (error) throw error;
  } catch (e) {
    console.error('Falha ao guardar', table, e);
  }
}

// Hook genérico de sincronização para as listas (jogadores, sessões,
// jogos, ...). Cada registo da lista vira UMA LINHA na respetiva tabela,
// o que permite saber quem editou cada registo individual — não só "a
// lista mudou". Compara a lista atual com a última versão sincronizada
// e só grava (upsert/apagar) o que realmente mudou; as alterações feitas
// por outra pessoa chegam sozinhas via tempo real.
function useCollectionSync(table, notifyEdit) {
  const [items, setItems] = useState([]);
  const [ready, setReady] = useState(false);
  const [recordMeta, setRecordMeta] = useState({}); // id -> { email, at }
  const snapshot = useRef(new Map()); // id -> JSON da última versão gravada

  useEffect(() => {
    let cancelled = false;
    (async () => {
      const { data, error } = await supabase.from(table).select('id, data, updated_by_email, updated_at').order('created_at', { ascending: true });
      if (cancelled) return;
      if (error) { console.error(table, error); setReady(true); return; }
      const rows = data || [];
      const snap = new Map();
      const meta = {};
      rows.forEach(r => { snap.set(r.id, JSON.stringify(r.data)); meta[r.id] = { email: r.updated_by_email, at: r.updated_at }; });
      snapshot.current = snap;
      setRecordMeta(meta);
      setItems(rows.map(r => ({ ...r.data, id: r.id })));
      setReady(true);
    })();
    return () => { cancelled = true; };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [table]);

  useEffect(() => {
    const channel = supabase.channel(`${table}_rt`)
      .on('postgres_changes', { event: '*', schema: 'public', table }, (payload) => {
        if (payload.eventType === 'DELETE') {
          const id = payload.old.id;
          snapshot.current.delete(id);
          setItems(prev => prev.filter(it => it.id !== id));
          setRecordMeta(prev => { const n = { ...prev }; delete n[id]; return n; });
        } else {
          const row = payload.new;
          snapshot.current.set(row.id, JSON.stringify(row.data));
          setItems(prev => {
            const item = { ...row.data, id: row.id };
            return prev.some(it => it.id === row.id) ? prev.map(it => it.id === row.id ? item : it) : [...prev, item];
          });
          setRecordMeta(prev => ({ ...prev, [row.id]: { email: row.updated_by_email, at: row.updated_at } }));
        }
      })
      .subscribe();
    return () => { supabase.removeChannel(channel); };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [table]);

  useEffect(() => {
    if (!ready) return;
    (async () => {
      const currentIds = new Set(items.map(it => it.id));
      const toUpsert = [];
      for (const it of items) {
        const { id, ...rest } = it;
        const json = JSON.stringify(rest);
        if (snapshot.current.get(id) !== json) toUpsert.push({ id, data: rest });
      }
      const toDelete = [];
      for (const id of snapshot.current.keys()) if (!currentIds.has(id)) toDelete.push(id);

      if (toUpsert.length) {
        const { data, error } = await supabase.from(table).upsert(toUpsert, { onConflict: 'id' }).select('id, data, updated_by_email, updated_at');
        if (error) { console.error(table, error); }
        else if (data) {
          data.forEach(r => {
            snapshot.current.set(r.id, JSON.stringify(r.data));
            setRecordMeta(prev => ({ ...prev, [r.id]: { email: r.updated_by_email, at: r.updated_at } }));
          });
        }
      }
      if (toDelete.length) {
        const { error } = await supabase.from(table).delete().in('id', toDelete);
        if (!error) toDelete.forEach(id => snapshot.current.delete(id));
        else console.error(table, error);
      }
      if (toUpsert.length || toDelete.length) notifyEdit(table);
    })();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [items, ready]);

  return [items, setItems, ready, recordMeta];
}

// Calcula a média de bem-estar de um registo de monitorização, usando
// apenas os campos que existirem (compatível com registos antigos, que
// tinham 'hidratação', e novos, que têm 'humor'/'stress' em vez disso).
function wellnessAvg(rec) {
  if (!rec) return null;
  const keys = ['sono', 'fadiga', 'dor', 'humor', 'stress', 'hidratacao'];
  const vals = keys.map(k => rec[k]).filter(v => typeof v === 'number');
  if (!vals.length) return null;
  return vals.reduce((a, b) => a + b, 0) / vals.length;
}

